select.addEventListener('change',()=>{if(select.value==='lounge')eventInput.checked=true;if(select.value==='neighborhood')contextInput.checked=true;applyView();save()});

root.querySelector('#gms-reset-btn').addEventListener('click',()=>{
  select.value='campus';
  select.dispatchEvent(new Event('change'));
});

function toggleFullscreen(){
  if(!document.fullscreenElement){
    host.requestFullscreen().catch(()=>{});
  } else {
    document.exitFullscreen().catch(()=>{});
  }
}
const fsBtn = root.querySelector('#gms-fullscreen-btn');
fsBtn.addEventListener('click', toggleFullscreen);
document.addEventListener('fullscreenchange', () => {
  if (document.fullscreenElement) {
    fsBtn.textContent = '✕ Exit Fullscreen';
    fsBtn.title = 'Exit Fullscreen (F or Esc)';
  } else {
    fsBtn.textContent = '⛶ Fullscreen';
    fsBtn.title = 'Toggle Fullscreen Canvas (F)';
  }
});

window.addEventListener('keydown', e => {
  if (['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName) || e.target.isContentEditable) return;
  if (e.key === 'f' || e.key === 'F') {
    e.preventDefault();
    toggleFullscreen();
  } else if (e.key === 'CapsLock' || e.code === 'CapsLock') {
    if (typeof depDeselect === 'function' && (typeof depSelected !== 'undefined' && depSelected || typeof depCamera !== 'undefined' && depCamera)) {
      e.preventDefault();
      depDeselect(true);
      return;
    }
  } else if (e.key === 'Escape') {
    if (typeof depDeselect === 'function' && (typeof depSelected !== 'undefined' && depSelected || typeof depCamera !== 'undefined' && depCamera)) {
      depDeselect(true);
      return;
    } else if (typeof depReturnView === 'function' && typeof depCamera !== 'undefined' && depCamera) {
      depReturnView();
      return;
    }
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(()=>{});
    }
  }
});

// Layers Toggle Popover
const layersToggle=root.querySelector('#gms-layers-toggle'), layersMenu=root.querySelector('#gms-layers-menu');
layersToggle.addEventListener('click',e=>{
  e.stopPropagation();
  layersMenu.classList.toggle('show');
});
document.addEventListener('click',e=>{
  if(!layersMenu.contains(e.target)&&!layersToggle.contains(e.target)) layersMenu.classList.remove('show');
});

eventInput.addEventListener('change',()=>{groups.event.visible=current!=='alignment'&&eventInput.checked;draw();save()});contextInput.addEventListener('change',()=>{groups.context.visible=current!=='alignment'&&contextInput.checked;draw();save()});
lightSelect.addEventListener('change',()=>{setLighting();draw();save()});
snapshotInput.addEventListener('change',()=>{groups.snapshot.visible=current!=='alignment'&&snapshotInput.checked;draw();save()});
let renderRequested=false;
controls.addEventListener('change',()=>{renderRequested=true;});
const navigation=root.querySelector('#gms-navigation'),canvas=renderer.domElement;
let motion=null,selection=null,suppressClick=false;
