function navigationMode(){
  if(navigation.value==='orbit'){
    controls.mouseButtons.LEFT=THREE.MOUSE.ROTATE;
    controls.mouseButtons.RIGHT=THREE.MOUSE.PAN;
  } else if(navigation.value==='pan') {
    controls.mouseButtons.LEFT=THREE.MOUSE.PAN;
    controls.mouseButtons.RIGHT=THREE.MOUSE.ROTATE;
  }
  root.querySelectorAll('#gms-mode-pills .mode-pill').forEach(btn=>{
    btn.classList.toggle('active', btn.dataset.mode===navigation.value);
  });
}
navigation.addEventListener('change',()=>{cancelBox();navigationMode();});
root.querySelectorAll('#gms-mode-pills .mode-pill').forEach(btn=>{
  btn.addEventListener('click',()=>{
    navigation.value=btn.dataset.mode;
    navigation.dispatchEvent(new Event('change'));
  });
});

